export const title = "Acoustic Panels vs. Soundproofing: What Helps in a Small Office?";
export const metaTitle = "Acoustic Panels vs. Soundproofing: What Helps";
export const metaDescription = "Learn when acoustic panels help room reflections and when sound transmission needs a different solution. A research-based guide from DeskFinds.";
export const author = "Jamie Cole, Lead Product Researcher";
